@dataclass(frozen=True)
class BalanceRoles:
    model: Deployment
    on_curve: dict
    balance: dict
    equivalent: dict
    compress: dict
    digest: str
    local_roles: tuple[int, int, int, int, int]
    global_roles: tuple[int, int, int, int, int, int, int]


def discover(circuit: str, module: str, shape: tuple[int, int]) -> BalanceRoles:
    model = Deployment.load(circuit, module, shape)
    on_curve = model.segment(
        "decaf.assert_on_curve",
        ("point=claimed.balance_commitment",),
    )
    balance = model.segment(
        "decaf.conservation_net_balance_commitment",
        (
            "inputs=input_amounts",
            "outputs=output_amounts",
            "blinding=action_balance_blinding",
            "out=balance_commitment.computed",
        ),
    )
    equivalent = model.segment(
        "decaf.assert_equivalent",
        (
            "lhs=balance_commitment.computed",
            "rhs=claimed.balance_commitment",
        ),
    )
    compress = model.segment(
        "decaf.compress_to_field",
        (
            "in=balance_commitment.computed",
            "out=balance_commitment.fq",
        ),
    )
    model.consecutive((balance, equivalent, compress))
    expected_templates = (
        "decaf.assert_on_curve@"
        "24bf85b2827b81673d6d4cc8defe8ee186fa904c91905b1d2fa2b9b734d52b7e",
        "decaf.assert_equivalent@"
        "44fe73acf05522f84376de4d4171a14b20527abf88695468311a6b63a8b891d7",
        "decaf.compress_to_field@"
        "f3cbec6d6a96bb84fc29e09f85870099785fe782098cecfd46860cf9527d762e",
    )
    if (
        on_curve["proof_template_id"],
        equivalent["proof_template_id"],
        compress["proof_template_id"],
    ) != expected_templates:
        raise ValueError(f"{circuit}: balance seam templates drifted")
    model.require_binding_role(
        on_curve,
        "claimed.balance_commitment",
        "input",
        exact=True,
        arity=2,
    )
    model.require_binding_role(
        balance,
        "balance_commitment.computed",
        "output",
        exact=True,
        arity=2,
    )
    model.require_binding_role(
        equivalent,
        "balance_commitment.computed",
        "input",
        arity=2,
    )
    model.require_binding_role(
        equivalent,
        "claimed.balance_commitment",
        "input",
        arity=2,
    )
    equivalent_inputs = (
        model.binding_wires("balance_commitment.computed", 2)
        | model.binding_wires("claimed.balance_commitment", 2)
    )
    if equivalent_inputs != set(equivalent["wire_roles"]["input"]):
        raise ValueError(
            f"{circuit}: balance-equivalence input role drifted"
        )
    model.require_binding_role(
        compress,
        "balance_commitment.computed",
        "input",
        arity=2,
    )
    model.require_binding_role(
        compress,
        "balance_commitment.fq",
        "output",
        exact=True,
        arity=1,
    )

    computed = model.binding("balance_commitment.computed", 2)
    compact = [
        family.compact_semantic_expression(expression)
        for expression in computed["expressions"]
    ]
    if any(
        len(runs) != 2
        or len(residual) != 1
        or any(run["coefficient"] != "1" for run in runs)
        or [(run["stride"], run["count"]) for run in runs]
        != [(5, 149), (8, 101)]
        for runs, residual in compact
    ):
        raise ValueError(f"{circuit}: balance output LC shape drifted")
    residual_wires = [residual[0]["wire_id"] for _, residual in compact]
    if len(set(residual_wires)) != 1:
        raise ValueError(f"{circuit}: balance accumulator residual drifted")
    run_wires = [
        compact[0][0][0]["start"],
        compact[1][0][0]["start"],
        compact[0][0][1]["start"],
        compact[1][0][1]["start"],
    ]
    balance_wires = [residual_wires[0], *run_wires]
    local_roles = tuple(model.local(balance, wire) for wire in balance_wires)

    fq = model.binding("balance_commitment.fq", 1)["expressions"][0]
    if fq["constant"] != "0" or len(fq["terms"]) != 2:
        raise ValueError(f"{circuit}: balance Fq binding shape drifted")
    fq_by_coefficient = {
        term["coefficient"]: term["wire_id"] for term in fq["terms"]
    }
    if len(fq_by_coefficient) != 2 or "1" not in fq_by_coefficient:
        raise ValueError(f"{circuit}: balance Fq coefficients drifted")
    negative = next(
        wire for coefficient, wire in fq_by_coefficient.items()
        if coefficient != "1"
    )
    positive = fq_by_coefficient["1"]
    if (
        model.local(compress, negative) != 864
        or model.local(compress, positive) != 1204
    ):
        raise ValueError(f"{circuit}: balance compression output seating drifted")
    return BalanceRoles(
        model=model,
        on_curve=on_curve,
        balance=balance,
        equivalent=equivalent,
        compress=compress,
        digest=template_digest(
            balance, "decaf.conservation_net_balance_commitment"
        ),
        local_roles=local_roles,
        global_roles=(
            residual_wires[0],
            *run_wires,
            negative,
            positive,
        ),
    )


def target_roles(config: Config) -> BalanceRoles:
    return discover(
        f"note_reshape{config.family}",
        config.module,
        (config.slots, 1),
    )


def local_map(source: BalanceRoles, target: BalanceRoles) -> dict[int, int]:
    return dict(zip(source.local_roles, target.local_roles, strict=True))


def global_map(source: BalanceRoles, target: BalanceRoles) -> dict[int, int]:
    return dict(zip(source.global_roles, target.global_roles, strict=True))


def replace_numbers(source: str, mapping: dict[int, int]) -> str:
    if not mapping:
        return source
    pattern = re.compile(
        r"(?<![A-Za-z0-9_])(" +
        "|".join(str(value) for value in sorted(mapping, reverse=True)) +
        r")(?![A-Za-z0-9_])"
    )
    return pattern.sub(lambda match: str(mapping[int(match.group(1))]), source)


def reviewed_template(path: Path) -> str:
    expected = REVIEWED_TEMPLATE_DIGESTS.get(path.name)
    if expected is None:
        raise ValueError(f"unreviewed balance template: {path}")
    try:
        payload = path.read_bytes()
        source = payload.decode("utf-8")
    except (OSError, UnicodeError) as error:
        raise ValueError(f"cannot read reviewed balance template: {path}") from error
    actual = hashlib.sha256(payload).hexdigest()
    if actual != expected:
        raise ValueError(
            f"reviewed balance template digest drifted: {path}: "
            f"{actual} != {expected}"
        )
    if source.startswith(GENERATED_HEADER):
        raise ValueError(
            f"reviewed balance template is marked generated: {path}"
        )
    return source


def primary_segment(path: Path, roles: BalanceRoles) -> dict:
    if "Cross" in path.stem:
        return roles.equivalent
    if "Compress" in path.stem:
        return roles.compress
    return roles.balance


def normalize_source(path: Path, source: str, roles: BalanceRoles) -> str:
    """Normalize one family-owned leaf to exact authenticated roles."""

    source = re.sub(r"by decide(?! \+kernel)", "by decide +kernel", source)
    source = re.sub(
        r"(?m)^(\s*)decide(?! \+kernel)$", r"\1decide +kernel", source
    )
    segment = primary_segment(path, roles)
    source = re.sub(r"\bSeg[0-9]+\b", f"Seg{segment['index']}", source)
    if path.stem.endswith("BalanceCross"):
        start = source.index("theorem claimedOnCurve")
        end = source.index("\ntheorem crossRatio", start)
        claimed = source[start:end]
        claimed = re.sub(
            r"\bSeg[0-9]+\b",
            f"Seg{roles.on_curve['index']}",
            claimed,
        )
        source = source[:start] + claimed + source[end:]
    source = re.sub(
        r"DecafConservationNetBalanceCommitmentSeg[0-9]+",
        "DecafConservationNetBalanceCommitmentSeg"
        f"{roles.balance['index']}",
        source,
    )
    source = re.sub(
        r"DecafAssertEquivalentSeg[0-9]+",
        f"DecafAssertEquivalentSeg{roles.equivalent['index']}",
        source,
    )
    source = re.sub(
        r"DecafCompressToFieldSeg[0-9]+",
        f"DecafCompressToFieldSeg{roles.compress['index']}",
        source,
    )
    source = re.sub(
        r"DecafAssertOnCurveSeg[0-9]+",
        f"DecafAssertOnCurveSeg{roles.on_curve['index']}",
        source,
    )
    source = re.sub(
        r"(TDecafConservationNetBalanceCommitment_)[0-9a-f]{64}",
        rf"\g<1>{roles.digest}",
        source,
    )

    by_index = {
        item["index"]: item
        for item in (
            roles.on_curve,
            roles.balance,
            roles.equivalent,
            roles.compress,
        )
    }
    number_map: dict[int, int] = {}
    equality = re.compile(
        r"Seg([0-9]+)\.wireSeating ([0-9]+) = ([0-9]+)"
    )
    for match in equality.finditer(source):
        segment_index, local, old_global = map(int, match.groups())
        exact_segment = by_index.get(segment_index)
        if exact_segment is None:
            raise ValueError(
                f"{roles.model.circuit}: unowned balance seating segment "
                f"{segment_index} in {path}"
            )
        seating = roles.model.seating(exact_segment)
        if local >= len(seating):
            raise ValueError(
                f"{roles.model.circuit}: local seat {local} is out of range "
                f"for segment {segment_index}"
            )
        new_global = seating[local]
        previous = number_map.setdefault(old_global, new_global)
        if previous != new_global:
            raise ValueError(
                f"{roles.model.circuit}: ambiguous stale wire {old_global}"
            )

    run_patterns = (
        re.compile(
            r"StrideRun\.sumAux \(Seg([0-9]+)\.localRho rho\) "
            r"([0-9]+) [0-9]+ [0-9]+ =\s+"
            r"StrideRun\.sumAux rho ([0-9]+)"
        ),
        re.compile(
            r"seatedRun_eq\s+rho ([0-9]+) ([0-9]+) [0-9]+ [0-9]+"
        ),
    )
    for pattern_index, pattern in enumerate(run_patterns):
        for match in pattern.finditer(source):
            if pattern_index == 0:
                segment_index, local, old_global = map(int, match.groups())
                exact_segment = by_index.get(segment_index)
                if exact_segment is None:
                    raise ValueError(
                        f"{roles.model.circuit}: unowned balance run segment "
                        f"{segment_index} in {path}"
                    )
            else:
                local, old_global = map(int, match.groups())
                exact_segment = segment
            seating = roles.model.seating(exact_segment)
            if local >= len(seating):
                raise ValueError(
                    f"{roles.model.circuit}: run seat {local} is out of range"
                )
            new_global = seating[local]
            previous = number_map.setdefault(old_global, new_global)
            if previous != new_global:
                raise ValueError(
                    f"{roles.model.circuit}: ambiguous run wire {old_global}"
                )
    return replace_numbers(source, number_map)


def render(
    path: Path,
    config: Config,
    source_roles: BalanceRoles | None = None,
    target: BalanceRoles | None = None,
) -> str:
    if source_roles is None:
        source_roles = discover(
            "note_reshape1x8", "NoteReshape1x8", (1, 8)
        )
    if target is None:
        target = target_roles(config)
    source = reviewed_template(path)
    normalized = normalize_source(path, source, source_roles)
    if normalized != source:
        raise ValueError(
            f"{source_roles.model.circuit}: reviewed balance template has "
            f"stale authenticated roles: {path}"
        )
    source = source.replace("NoteReshape1x8", f"NoteReshape{config.family}")
    source = source.replace("1x8", config.family)
    source = source.replace(source_roles.digest, target.digest)
    segment_map = {
        source_roles.balance["index"]: target.balance["index"],
        source_roles.equivalent["index"]: target.equivalent["index"],
        source_roles.compress["index"]: target.compress["index"],
        source_roles.on_curve["index"]: target.on_curve["index"],
    }
    for old, new in segment_map.items():
        source = re.sub(rf"\bSeg{old}\b", f"Seg{new}", source)
    source = re.sub(
        r"DecafConservationNetBalanceCommitmentSeg[0-9]+",
        "DecafConservationNetBalanceCommitmentSeg"
        f"{target.balance['index']}",
        source,
    )
    source = re.sub(
        r"DecafAssertEquivalentSeg[0-9]+",
        f"DecafAssertEquivalentSeg{target.equivalent['index']}",
        source,
    )
    source = re.sub(
        r"DecafCompressToFieldSeg[0-9]+",
        f"DecafCompressToFieldSeg{target.compress['index']}",
        source,
    )
    source = re.sub(
        r"DecafAssertOnCurveSeg[0-9]+",
        f"DecafAssertOnCurveSeg{target.on_curve['index']}",
        source,
    )
    source = replace_numbers(source, global_map(source_roles, target))
    if any(
        token in path.stem
        for token in ("BalanceAccFinal", "BalanceRun", "BalanceRuns")
    ) and not any(token in path.stem for token in ("Cross", "Compress")):
        source = replace_numbers(source, local_map(source_roles, target))
    return GENERATED_HEADER + source


def check_generated(path: Path, expected: str) -> None:
    if not path.is_file() or path.read_text(encoding="utf-8") != expected:
        raise SystemExit(f"generated file is stale: {path}")


def validate_reviewed_roster(
    prefix: str, roles: BalanceRoles
) -> tuple[Path, ...]:
    """Authenticate one complete handwritten balance-seam family."""

    expected_names = {
        name
        for name in REVIEWED_TEMPLATE_DIGESTS
        if name.startswith(prefix)
    }
    actual_names = {
        path.name for path in DEPLOYED.glob(f"{prefix}*.lean")
    }
    if actual_names != expected_names:
        raise ValueError(
            f"reviewed {prefix} roster drifted: "
            f"{sorted(actual_names ^ expected_names)}"
        )
    paths = tuple(DEPLOYED / name for name in sorted(expected_names))
    for path in paths:
        source = reviewed_template(path)
        if normalize_source(path, source, roles) != source:
            raise SystemExit(
                f"reviewed balance template roles are stale: {path}"
            )
    return paths


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "families",
        nargs="*",
        choices=[config.selector for config in CONFIGS],
    )
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    selected = set(args.families) if args.families else {
        config.selector for config in CONFIGS
    }
    source_roles = discover(
        "note_reshape1x8", "NoteReshape1x8", (1, 8)
    )
    source_paths = validate_reviewed_roster(SOURCE_PREFIX, source_roles)
    for config in CONFIGS:
        if config.selector not in selected:
            continue
        target_role_data = target_roles(config)
        target_main = DEPLOYED / f"{config.target_prefix}.lean"
        main_source = reviewed_template(target_main)
        if (
            normalize_source(target_main, main_source, target_role_data)
            != main_source
        ):
            raise SystemExit(
                f"reviewed balance template roles are stale: {target_main}"
            )
        for path in source_paths:
            if path.name in EXCLUDED:
                continue
            target = DEPLOYED / path.name.replace(
                SOURCE_PREFIX, config.target_prefix, 1
            )
            expected = render(
                path, config, source_roles, target_role_data
            )
            if args.check:
                check_generated(target, expected)
            elif write_if_changed(target, expected):
                print(target)


if __name__ == "__main__":
    main()
